document.addEventListener('DOMContentLoaded', () => {
    const offcanvas = document.getElementById('wooshop-mini-cart');

    let bootstrap;
    if (!offcanvas || typeof bootstrap === 'undefined') {
        return;
    }

    document.body.addEventListener('wc_fragments_refreshed', () => {
        const cart = bootstrap.Offcanvas.getOrCreateInstance(offcanvas);

        if (cart) {
            offcanvas.dispatchEvent(new CustomEvent('wooshop:cart-updated'));
        }
    });
});